                {
                    "name": "result",
                    "parts": [{"kind": "text", "text": result_text}],
                    "metadata": {"type": "text", "checks_passed": 12, "checks_total": 12},
                }
            ],
        }
        self.tasks[task_id] = task
        self.calls[-1]["resume"] = is_resume
        return task

